namespace sv_f260d524e25d4709bf98ba9c9d83f762.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_f260d524e25d4709bf98ba9c9d83f762.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

<div class="catalog-layout">
    @* ── Left Sidebar ── *@
    <aside class="catalog-sidebar">
        <h5>Filters</h5>

        @if (categories is not null)
        {
            <div class="filter-section">
                <label class="fw-semibold">Category</label>
                @foreach (var cat in categories)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                               checked="@selectedCategories.Contains(cat)"
                               @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                        <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                    </div>
                }
            </div>
        }

        <div class="filter-section">
            <label class="fw-semibold">Price Range</label>
            <div class="d-flex gap-2 align-items-center">
                <input type="number" class="form-control form-control-sm" placeholder="Min"
                       @bind="minPrice" @bind:event="oninput" min="0" />
                <span>&ndash;</span>
                <input type="number" class="form-control form-control-sm" placeholder="Max"
                       @bind="maxPrice" @bind:event="oninput" min="0" />
            </div>
        </div>

        <div class="filter-section">
            <div class="form-check">
                <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="inStockOnly" />
                <label class="form-check-label" for="inStockOnly">In Stock Only</label>
            </div>
        </div>

        <div class="d-flex flex-column gap-2 mt-3">
            <button class="btn btn-primary btn-sm" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    @* ── Main Content ── *@
    <section class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @errorMessage
            </div>
        }
        else if (isLoading)
        {
            <div class="d-flex justify-content-center align-items-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading…</span>
                </div>
                <span class="ms-3">Loading products…</span>
            </div>
        }
        else if (pagedResult is not null && pagedResult.Items.Count == 0)
        {
            <div class="alert alert-info" role="alert">
                No products found matching your filters.
            </div>
        }
        else if (pagedResult is not null)
        {
            @* Toolbar *@
            <div class="catalog-toolbar">
                <div class="d-flex align-items-center gap-3">
                    <label class="text-nowrap" for="sortSelect">Sort by:</label>
                    <select id="sortSelect" class="form-select form-select-sm w-auto" @bind="sortBy" @bind:after="LoadProducts">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A-Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>

                <span class="text-muted">
                    Showing @ShowingStart–@ShowingEnd of @pagedResult.TotalCount products
                </span>
            </div>

            @* Product Grid *@
            <div class="product-grid">
                @foreach (var product in pagedResult.Items)
                {
                    <ProductCard Product="product" OnProductSelected="OnProductSelected" />
                }
            </div>

            @* Pagination *@
            @if (TotalPages > 1)
            {
                <nav aria-label="Product pagination" class="mt-4">
                    <ul class="pagination justify-content-center">
                        <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                            <button class="page-link" @onclick="() => GoToPage(currentPage - 1)" disabled="@(currentPage == 1)">Previous</button>
                        </li>
                        @for (int i = 1; i <= TotalPages; i++)
                        {
                            var pageNum = i;
                            <li class="page-item @(pageNum == currentPage ? "active" : "")">
                                <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
                            </li>
                        }
                        <li class="page-item @(currentPage == TotalPages ? "disabled" : "")">
                            <button class="page-link" @onclick="() => GoToPage(currentPage + 1)" disabled="@(currentPage == TotalPages)">Next</button>
                        </li>
                    </ul>
                </nav>
            }
        }
    </section>
</div>

@code {
    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;

    private PagedResult<Product>? pagedResult;
    private bool isLoading = true;
    private string? errorMessage;

    private int TotalPages => pagedResult is null || pagedResult.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)pagedResult.TotalCount / PageSize);

    private int ShowingStart => pagedResult is null || pagedResult.Items.Count == 0
        ? 0
        : (pagedResult.Page - 1) * pagedResult.PageSize + 1;

    private int ShowingEnd => pagedResult is null
        ? 0
        : ShowingStart + pagedResult.Items.Count - 1;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
            await LoadProducts();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
            isLoading = false;
        }
    }

    private async Task LoadProducts()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            StateHasChanged();

            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            pagedResult = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages) return;
        currentPage = page;
        await LoadProducts();
    }

    private void OnProductSelected(Product product)
    {
        // Parent-level hook: could be wired to NavigationManager.NavigateTo($"/catalog/{product.Id}")
    }
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    border-right: 1px solid #dee2e6;
    padding-right: 1.5rem;
}

.catalog-main {
    flex: 1 1 75%;
    min-width: 0;
}

.filter-section {
    margin-bottom: 1rem;
}

.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid #dee2e6;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

@using sv_f260d524e25d4709bf98ba9c9d83f762.Services

<div class="product-card card h-100" @onclick="HandleCardClick" role="button">
    <div class="card-img-placeholder" title="@Product.Name">
        @Product.Name
    </div>
    <div class="card-body d-flex flex-column">
        <h6 class="card-title mb-1">@Product.Name</h6>
        <p class="card-text fw-bold mb-1">@Product.Price.ToString("C")</p>
        <div class="mb-2 star-rating" aria-label="@($"Rating: {Product.Rating:F1} out of 5")">
            @for (int i = 1; i <= 5; i++)
            {
                @(i <= (int)Math.Round(Product.Rating) ? "★" : "☆")
            }
        </div>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2">Out of Stock</span>
        }
        <button class="btn btn-sm btn-success mt-auto"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private void HandleAddToCart()
    {
        // Cart logic placeholder
    }
}

.product-card {
    cursor: pointer;
    transition: box-shadow 0.15s ease-in-out;
}

.product-card:hover {
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.15);
}

.card-img-placeholder {
    height: 160px;
    background-color: #e9ecef;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #6c757d;
    font-size: 0.875rem;
    text-align: center;
    padding: 1rem;
    border-bottom: 1px solid #dee2e6;
}

.star-rating {
    color: #ffc107;
    font-size: 1rem;
    letter-spacing: 1px;
}

