@using sv_f260d524e25d4709bf98ba9c9d83f762.Services

<div class="product-card card h-100" @onclick="HandleCardClick" role="button">
    <div class="card-img-placeholder" title="@Product.Name">
        @Product.Name
    </div>
    <div class="card-body d-flex flex-column">
        <h6 class="card-title mb-1">@Product.Name</h6>
        <p class="card-text fw-bold mb-1">@Product.Price.ToString("C")</p>
        <div class="mb-2 star-rating" aria-label="@($"Rating: {Product.Rating:F1} out of 5")">
            @for (int i = 1; i <= 5; i++)
            {
                @(i <= (int)Math.Round(Product.Rating) ? "★" : "☆")
            }
        </div>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2">Out of Stock</span>
        }
        <button class="btn btn-sm btn-success mt-auto"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private void HandleAddToCart()
    {
        // Cart logic placeholder
    }
}

.product-card {
    cursor: pointer;
    transition: box-shadow 0.15s ease-in-out;
}

.product-card:hover {
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.15);
}

.card-img-placeholder {
    height: 160px;
    background-color: #e9ecef;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #6c757d;
    font-size: 0.875rem;
    text-align: center;
    padding: 1rem;
    border-bottom: 1px solid #dee2e6;
}

.star-rating {
    color: #ffc107;
    font-size: 1rem;
    letter-spacing: 1px;
}

